-- Tabelle CaRGOS (Polizia di Stato): luoghi, per l'invio automatico dei contratti.
CREATE TABLE `cargos_places` (`code` integer PRIMARY KEY NOT NULL, `name` text NOT NULL, `province` text, `kind` text NOT NULL);
CREATE INDEX `cargos_places_name_idx` ON `cargos_places` (`name`);
ALTER TABLE `customers` ADD `birth_place_code` integer;
